<?php
// Run once from the command line when upgrading an existing Lab 6 database.
declare(strict_types=1); require_once dirname(__DIR__).'/config/db.php';
$pdo=openDatabase();$pdo->exec("CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");$pdo->exec("CREATE TABLE IF NOT EXISTS user_roles (user_id INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('student','tutor','admin')), PRIMARY KEY(user_id,role), FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE)");$names=array_column($pdo->query('PRAGMA table_info(students)')->fetchAll(),'name');if(!in_array('user_id',$names,true))$pdo->exec('ALTER TABLE students ADD COLUMN user_id INTEGER REFERENCES users(user_id)');$pdo->exec('CREATE UNIQUE INDEX IF NOT EXISTS idx_students_user_id ON students(user_id)');echo "Migration complete. Existing student records remain unlinked until an administrator deliberately links accounts.\n";
